// Xiaochu: deterministic, source-backed local knowledge. No model, keys or remote chat requests.
import {exhibits,categories} from './content.mjs';
import {translateText} from './i18n.mjs';

const heritageSource={title:'中国非物质文化遗产网 · 项目名录与门类',url:'https://www.ihchina.cn/Project/Index'};
const livingSource={title:'UNESCO · What is intangible cultural heritage?',url:'https://ich.unesco.org/en/what-isintangible-heritage-00003'};
const safeguardingSource={title:'UNESCO · Safeguarding without freezing',url:'https://ich.unesco.org/en/safeguarding-00012'};
const sleepSource={title:'NHS · Sleep problems',url:'https://www.nhs.uk/every-mind-matters/mental-health-issues/sleep/'};
const faq=(id,keys,zh,en,group='life',sources=[],section='')=>({id,keys:keys.split('|'),zh,en,group,sources,section});

export const KNOWLEDGE_CARDS=[
 faq('identity','你是谁|你叫什么|介绍自己|你是ai吗|你是真人吗|who are you|your name|are you ai','我是小楚，荆楚非遗的知识库导览助手。可以帮你找非遗、看图片、认识地图和三维，也能聊聊学习与日常安排。我按本站资料和预先整理的内容回答，没有接入大模型，也不是真人。','I am Xiaochu, the gallery’s local knowledge guide. I can find heritage entries, photographs, maps and 3D exhibits, and offer simple study and everyday suggestions. I use curated content, not a large language model or a human operator.','site'),
 faq('scope','你会什么|能做什么|怎么问你|帮助菜单|what can you do|what can i ask|help menu','你可以问：“通山木雕有什么特点？”“武汉有哪些非遗？”“哪些展品能看三维？”“非遗和文物有什么区别？”也可以说“学习没动力”或“周末怎么安排”。我会附上能核对的来源；没有收录的信息会说明。','Try “What is special about Tongshan wood carving?”, “What heritage is in Wuhan?”, “Which exhibits have 3D models?” or “How do I start studying?”. I show available sources and explain when the collection does not contain an answer.','site'),
 faq('knowledge','知识库有多少|有多少资料|数据从哪里来|资料来源|knowledge base|where is your information from','我复用本站146条地区记录与专题、图片关联、双语导读和8个文化目的地，并补充非遗入门、展馆帮助与日常交流。文化内容的来源会显示在回答下方。146条是地区记录与专题数，并非146种互不重复的非遗。','I reuse 146 regional entries and topics, bilingual guides, linked photographs and eight visit destinations, plus introductory, gallery-help and everyday cards. Cultural sources appear below answers. The 146 entries are not 146 distinct heritage traditions.','site'),
 faq('no-cost','要收费吗|免费吗|要付费吗|调用费用|do you charge|is this free|api cost','这个助手不调用大模型，没有按次问答的模型费用。问题在当前浏览器中处理；打开外部来源、街道地图或导航时，才会访问相应外部服务。','This assistant makes no large-model calls and has no per-answer model charge. Questions are processed in this browser. External sources, street maps and navigation use their own services when you open them.','site'),
 faq('privacy','聊天会上传吗|聊天记录|隐私|会保存聊天吗|privacy|save my chat|upload my question','聊天内容只保留在当前页面内存中，不发送给问答服务器、不写入浏览器持久存储。刷新页面或“清空对话”会清除本页对话；阅读、收藏与行程是网站原有的独立记录。','Chat stays in this page’s memory. It is not sent to a chat server or written to persistent storage. Refreshing or clearing chat removes this conversation. Existing reading, favourites and trip records are separate.','site'),
 faq('language','切换英文|切换中文|切换语言|怎么用英文|change language|switch language|english mode','可以用网站右上角的语言选择器，也可以用聊天面板里的“EN／中文”按钮。助手能查找中英文名称；生活建议也准备了两种语言。','Use the website language selector or the EN / 中文 button in this panel. The assistant recognises Chinese and English names and has bilingual everyday cards.','site'),
 faq('search','怎么搜索非遗|怎么找非遗|搜索怎么用|search the collection|how to search','在图鉴输入名称或关键词，再按地区、门类筛选；条件会一起生效。你也可以直接告诉我一个名称、地区或门类，我会给出相关条目。','Enter a name or keyword in the collection, then filter by region and category. Filters work together. You can also ask me for a name, city or category.','site',[],'collection'),
 faq('favourite','怎么收藏|如何收藏|收藏在哪|收藏怎么用|how to favourite|how to favorite|save a favourite','在图鉴卡片上点“收藏”，再勾选“只看收藏”即可集中查看。收藏保存在当前浏览器；换设备或清理网站数据后不会自动恢复。','Select Favourite on an entry, then enable the favourites-only filter. Favourites are stored in this browser and do not automatically follow you to another device.','site',[],'collection'),
 faq('reading','怎么记手记|阅读记录|怎么标记已读|读完记手记|reading progress|mark as read','打开专题，点击“读完，记入手记”。学习区域会更新已读数。想留一份副本，可以使用“导出手记”；它和清空助手对话是两回事。','Open an entry and choose Mark as read. The learning area updates your progress. Export your notes to keep a copy; this is separate from clearing chat.','site',[],'learn'),
 faq('quiz','怎么答题|知识小测|十题挑战|三题入门|how to take a quiz|quiz modes','学习手记里有三题入门与十题挑战。选答案后提交，就能查看解析和练习历史。它用于个人学习，不是有身份认证的正式考试。','The learning area has a three-question introduction and a ten-question challenge. Submit to see explanations and local history. These are personal practice quizzes.','site',[],'learn'),
 faq('map-help','地图怎么用|怎么用地图|数字点什么意思|菱形什么意思|how to use the map|map markers','数字点表示同一参考位置的非遗记录数，点开能看相关专题；菱形是已收录的参观目的地，可以加入行程。地区参考点不等于场馆入口。','Numbered markers group heritage records at the same reference position. Open one for related topics. Diamonds mark visit destinations that can be added to a trip. Regional points are not venue entrances.','site',[],'atlas'),
 faq('blank-map','地图空白|底图空白|地图打不开|blank map|map will not load','先使用默认“非遗分布图”。它的轮廓随本站加载，不依赖外部街道瓦片；在线街道图连接失败会回退。若轮廓也没有，可刷新页面、检查网络，图鉴仍可使用。','Try the default heritage distribution map. Its boundaries ship with this site, and a failed street layer falls back to it. If boundaries also fail, refresh and check connectivity; the collection remains usable.','site',[],'atlas'),
 faq('route-help','怎么规划路线|如何规划行程|怎么加入行程|生成道路路线|plan a route|plan a trip|add to trip','在地图上选文化目的地并点“加入行程”，至少选2站，再点“生成道路路线”。最多8站。虚线只表示顺序，查询成功后的实线才是道路结果。','Add at least two cultural destinations from the map, then choose Generate road route. A trip has at most eight stops. Dashed lines show order; a successful road query supplies the actual route.','site',[],'atlas'),
 faq('route-optimise','顺路排序|最短路线|路线最优|optimize route|optimise route|shortest trip','“顺路排序”每次选择直线距离较近的下一站，方便安排小行程，但不保证驾车全程最省时。道路里程与估算时间来自OSRM，不包含实时路况或游览停留。','Suggested order repeatedly chooses a nearby next stop by straight-line distance. It does not guarantee the fastest driving tour. OSRM supplies road distances and estimates without live traffic or visit time.','site',[],'atlas'),
 faq('navigation','怎么导航|高德导航|公交路线|步行导航|如何去场馆|open navigation|public transport|walking route','先选已收录的参观目的地，再用行程中的高德驾车、公交或步行链接继续导航。本站不会自动获取你的实时位置，入口与开放情况请在场馆官方渠道确认。','Choose a listed destination and use its Amap driving, public-transport or walking link. This site does not automatically obtain your live location. Check entrances and opening arrangements with the venue.','site',[],'atlas'),
 faq('3d-help','怎么打开三维|怎么进入三维|三维怎么用|打开3d|打开三维|how to open 3d|start 3d|use 3d','进入“三维体验”，选择陶器、木雕、编钟或戏台，再主动点击开始。首次核心资源约348 MiB，适合电脑和稳定网络。助手不会自动下载三维大文件。','Go to 3D Experience, select pottery, wood carving, bells or theatre, and start explicitly. The first core download is about 348 MiB. A computer and stable connection are preferable. Chat never starts that download automatically.','site',[],'experience'),
 faq('3d-slow','三维卡|三维打不开|模型打不开|三维很慢|模型加载失败|3d slow|3d not loading|model will not load','首次三维资源较大，请保持稳定网络并等待加载状态。失败时可结束体验后重试，必要时刷新；图鉴和地图可以先继续使用。旧场景的卡顿并不都能通过网页设置解决。','The initial 3D assets are large. Keep a stable connection and watch the loading state. Retry after ending the experience, or refresh if necessary. Reading and maps remain available; some legacy scene slowdowns need engine changes.','site',[],'experience'),
 faq('camera','视角怎么调|怎么转视角|右键画画|鼠标手势|第一人称|第三人称|camera control|first person|third person|right mouse','戏台环视模式下可按住左键拖动调整视角，操作场景按钮时切回点击模式。原右键可能触发浏览器手势，所以做了左键兼容。当前没有第一／第三人称切换入口。','In theatre look mode, drag with the left mouse button; switch to click mode for scene controls. This avoids right-button browser gestures. A first-/third-person switch is not implemented.','site',[],'experience'),
 faq('photo-help','图片在哪里|怎么放大图片|图片授权|照片来源|where are the photos|photo credits|image licence','“非遗影像”里可放大图片并进入相关专题。每张保留作者、授权和范围说明；同类工艺参考图不一定是本地项目的实物照片。','The photo gallery supports enlarged viewing and related entries. Each image keeps author, licence and scope information; an art-form reference is not necessarily a photograph of the local project.','site',[],'gallery'),
 faq('video-help','视频打不开|视频在哪里|影音课堂|video not loading|where is the video','影音课堂提供荆州花鼓戏《三官堂》3分钟节选，保留原片头署名，点击案例按钮后再播放。也可以选择自己的本地视频，文件在当前浏览器预览，不会由这个功能上传。','The media area includes a three-minute excerpt of Jingzhou Huagu opera Sanguantang, preserving the original on-screen credits. Open the example and use the player controls. You can also preview your own local video without uploading it.','site',[],'media'),
 faq('storage-help','记录不见|收藏丢失|换手机记录|同步记录|lost my progress|sync my notes','收藏、阅读和行程按浏览器保存。无痕模式、清理网站数据、换浏览器或换设备，都可能看不到原记录。目前没有账号云同步，建议定期导出学习手记。','Favourites, reading and trips are browser-local. Private mode, clearing site data or changing browser/device can hide earlier records. There is no account sync; export your notes periodically.','site',[],'learn'),
 faq('offline','离线使用|没有网络能用吗|offline use|without internet','本助手的回答逻辑和知识文件随网站提供，加载完成后不依赖外部大模型。网站不是完整离线应用；首次打开、外部来源、街道、道路查询和导航仍需要相应网络连接。','Once its files are loaded, this assistant needs no external model. The site is not a full offline app: first loading, external sources, streets, road queries and navigation still need connectivity.','site'),
 faq('heritage-definition','什么是非遗|非遗是什么|非物质文化遗产是什么|what is intangible cultural heritage|what is ich','非遗是人们在生活中传承的知识、技艺、表达与实践，例如地方戏曲、传统工艺和节俗。重点不只是一件成品，而是人怎样掌握、使用和传下去。','Intangible heritage includes living knowledge, skills, expressions and practices, such as performing arts, crafts and customs. Its importance includes how people practise and transmit it, not only the finished object.','culture',[livingSource]),
 faq('living-heritage','活态传承|活态性|非遗能创新吗|非遗会变化吗|living heritage|can heritage change','“活态”强调传统仍在人的生活中实践和传承。保护也需要尊重社区参与，不能只把传统固定成一件展示品；变化与创新应理解其文化意义和传承关系。','Living heritage is practised and passed on by people. Safeguarding involves communities and transmission rather than freezing a display object. Change should be considered in its cultural and transmission context.','culture',[safeguardingSource]),
 faq('tangible','非遗和文物|非遗和物质遗产|非遗与文物|heritage and artefacts|tangible and intangible','文物或器物是可以看见、保存的实体；非遗侧重人掌握的知识、技艺、表达和实践。两者常有关联：编钟是器物，制作、校音或相关演奏知识则涉及人的技艺。','An artefact is a tangible object; intangible heritage focuses on practised knowledge, skills and expression. They can be connected: bells are objects, while making, tuning and performing involve human knowledge.','culture',[livingSource]),
 faq('categories','非遗有哪些门类|十大门类|非遗分几类|ten categories|heritage categories','国家级非遗名录使用十个门类：民间文学、传统音乐、传统舞蹈、传统戏剧、曲艺、传统体育／游艺与杂技、传统美术、传统技艺、传统医药、民俗。你可以继续问某类在本站有哪些项目。','China’s national inventory uses ten categories: folk literature; traditional music; dance; theatre; narrative arts; sports, recreation and acrobatics; fine arts; craftsmanship; medicine; and folk customs. Ask for entries in any category.','culture',[heritageSource]),
 faq('same-name','同名非遗|为什么同名|同一个非遗不同地区|same name different regions','同名项目可能在不同地区有不同传承情况、特征和保护单位。本站保留地区子项，查资料时要同时看名称与地区；不能把一个地区的细节自动套到另一个地区。','A named tradition can have regional subentries with different characteristics, transmission and safeguarding bodies. Check both name and region; details from one region do not automatically describe another.','culture',[heritageSource]),
 faq('safeguard','怎么保护非遗|如何保护非遗|普通人能做什么|safeguard heritage|support heritage','先了解项目和社区认可的实践，阅读可靠来源，尊重演出、拍摄与学习规则；有条件时参加公开讲解或正规体验。传播时保留名称、地区和出处，少用猎奇或未经核实的故事。','Read reliable sources, respect community practices and photography or learning rules, and join public interpretation or appropriate workshops. When sharing, retain names, regions and sources instead of unverified stories.','culture',[safeguardingSource]),
 faq('learn-craft','怎么学手艺|学习非遗从哪开始|零基础学非遗|learn a craft|begin learning heritage','可以按“看—问—试—记”开始：先看作品和来源，再了解材料与步骤；选择公开、合适的基础体验，记录自己的观察。涉及高温、刀具或专门操作时，应有合适指导和条件。','Start by observing, asking, trying a suitable beginner activity and taking notes. Learn materials and steps from reliable sources. Activities involving heat, blades or specialist processes need appropriate supervision and conditions.','culture'),
 faq('observe','怎么看懂一件作品|欣赏非遗|怎么观察器物|observe a craft|appreciate an object','先看用途和整体形状，再看材料、表面纹理、结构和装饰，最后问“这些特点与制作、使用有什么联系”。本站专题中的观察提示可以当作看图或看三维的提问清单。','Look at purpose and overall form, then materials, texture, structure and decoration. Ask how these relate to making and use. Each entry’s observation prompts can guide photo or 3D viewing.','culture',[],'collection'),
 faq('embroidery','刺绣怎么看|针法是什么|怎么看刺绣|look at embroidery|embroidery stitches','观察刺绣可以先看底料、线材、针线方向、密度与图案层次。不同地区和绣种有各自特点，想看本站例子可以问“汉绣”或“阳新布贴”。','When viewing embroidery, look at fabric, threads, stitch direction, density and layers. Traditions differ by region; ask about Han embroidery or Yangxin cloth appliqué for examples in this collection.','culture'),
 faq('craft-photo','三维模型是真文物吗|图片等于工艺吗|模型和实物|is the model an artefact|model and original','模型与图片是帮助观察的展示材料，不自动等于真实文物、完整制作过程或声音复原。阅读时同时看图注、模型说明和来源，区分实物照片、历史器物与同类参考。','Models and images are aids to observation, not automatically original artefacts, complete processes or acoustic reconstructions. Check captions and sources to distinguish originals, historic objects and references.','culture'),
 faq('hubei-chu','荆楚是什么意思|荆楚是什么|jingchu meaning|what does jingchu mean','本站用“荆楚”作为湖北文化主题的名称。具体项目仍按各自的地区和来源介绍，避免把湖北所有传统都说成同一种风格。可以从武汉、荆州、宜昌、随州或恩施开始查。','This gallery uses Jingchu as its Hubei cultural theme. Individual entries retain their own regions and sources, rather than being treated as one uniform style. Try Wuhan, Jingzhou, Yichang, Suizhou or Enshi.','culture'),
 faq('greeting','你好|你好呀|你好啊|您好|嗨|哈喽|在吗|有人吗|hello|hi|hey|早安|午安|早上好|下午好|晚上好','你好呀，我是小楚。想先认识一门非遗，还是聊聊今天的安排？可以试试“今天推荐一个非遗”或“学习没动力”。','Hello, I am Xiaochu. Shall we explore a tradition or plan a small part of your day? Try “Recommend some heritage” or “I cannot get started studying”.'),
 faq('thanks','谢谢|谢谢你|太谢谢了|感谢|感谢你|多谢|thank you|thanks|thank u|thank you very much|thanks a lot','不客气，能帮你理清一点就好。想继续了解刚才的项目，也可以问“它在哪里”或“有什么值得观察”。','You are welcome. You can continue with “Where is it from?” or “What should I look for?” about the previous entry.'),
 faq('goodbye','再见|拜拜|晚安|goodbye|bye|good night','下次再来逛逛。可以把感兴趣的专题收藏起来，给下一次探索留个入口。','See you next time. Favourite an entry you enjoyed as a starting point for another visit.'),
 faq('bored','无聊|没事做|不知道干什么|好无聊|bored|nothing to do','要不要试一个很小的探索：找一张喜欢的非遗图片，说出三个细节，再打开对应专题核对？也可以给自己留一段不安排任务的休息时间。','Try a small exploration: pick a photo, name three details and open its entry to learn more. Leaving some time without a task is also an option.'),
 faq('chat','陪我聊聊|聊聊天|陪我说说话|随便聊聊|chat with me|talk to me','可以呀。你今天更想聊学习、出行，还是想找一件好看的器物放松一下？我能按这些已有话题接着聊；复杂的私人经历，和信任的人交流也很重要。','Sure. Would you like to talk about studying, a visit, or a beautiful object? I can follow these curated topics. For complex personal experiences, talking with someone you trust can help too.'),
 faq('tired','有点累|好累|累了|疲惫|太累|i am tired|feeling tired','今天可能已经消耗不少精力了。可以先暂停一小会儿，放下屏幕、调整一下坐姿，再决定接下来只做哪一件小事。休息不需要先“完成所有事情”。','It sounds like you have spent a lot of energy. Pause briefly, put the screen down and get comfortable, then choose just one small next step. Rest need not wait until everything is finished.'),
 faq('sad','心情不好|不开心|难过|有点低落|feeling sad|feel down|unhappy','听起来今天有点不好过。可以先把让你难受的事情写成一句话，再想一个此刻能照顾自己的小动作。如果愿意，也可以和信任的人说说，不必独自把所有感受处理完。','That sounds like a difficult day. Try writing one sentence about what feels hard and choosing one small caring action now. You can also talk with someone you trust; you need not work through everything alone.'),
 faq('worry','压力大|很焦虑|担心|紧张|好烦|stressed|anxious|worried','先把事情分成“现在能做的一步”和“暂时不能决定的部分”。从前一类挑最小的一步，给自己留一点缓冲。若这些感受持续影响日常生活，找信任的人或合适的专业支持聊聊会更稳妥。','Separate what you can do now from what you cannot decide yet. Choose the smallest step in the first group and allow some breathing room. If feelings persist and affect daily life, consider trusted or professional support.'),
 faq('lonely','孤独|寂寞|没人聊天|一个人好难|lonely|no one to talk to','一个人待着的时候，想有人回应是很自然的。可以给熟悉的人发一句具体的话，比如“今天有点累，想聊十分钟”。我也能陪你选个小话题，但现实中的联系同样值得保留。','Wanting a response when you are alone is understandable. Try a specific message to someone familiar, such as “I have had a tiring day; could we talk for ten minutes?”. I can offer a small topic too, alongside real-world connections.'),
 faq('motivation','没动力|不想学习|学不进去|不想工作|cannot start studying|no motivation','先别把目标设成“学完一整章”。试着只打开资料、写出一个问题，完成后再决定要不要继续。开始的门槛越小，越容易知道自己究竟卡在内容、疲劳还是任务太模糊。','Instead of finishing a whole chapter, start by opening the material and writing one question. Then decide whether to continue. A small start helps reveal whether the obstacle is content, tiredness or an unclear task.'),
 faq('procrastination','拖延|总是拖|拖到最后|procrastinat','把任务改成一个能看到的动作，例如“给报告写三行提纲”，而不是“把报告搞好”。提前准备要用的文件，先做最容易开始的一步，再检查下一步。','Turn the task into a visible action, such as writing three outline lines, rather than “finish the report”. Prepare the files and begin with the easiest concrete step, then review what comes next.'),
 faq('plan-day','安排一天|时间管理|怎么做计划|今日计划|plan my day|time management|daily plan','可以写三栏：今天必须完成、可以推进、留给自己。第一栏只放少量真正必要的事，为移动和休息留空，不把每分钟都塞满。晚上简单回看什么做到了，再调整明天。','Use three groups: essential today, useful progress, and time for yourself. Keep essentials few and leave room for breaks and travel. Review what happened this evening and adjust tomorrow.'),
 faq('focus','专注|注意力不集中|容易分心|刷手机停不下来|focus better|distracted|keep scrolling','先把这段时间要做的事写成一句话，关掉无关提醒，把暂时想到的事记在旁边。专注时段长短按自己的状态调整；结束后检查一个具体结果，不用只计算坐了多久。','Write one task for this session, mute unrelated notifications and keep a side note for distractions. Adjust session length to your needs and check a concrete result rather than only time spent sitting.'),
 faq('notes','怎么记笔记|笔记怎么做|读书笔记|take notes|study notes','试试三行笔记：第一行“讲了什么”，第二行“依据或例子是什么”，第三行“我还有什么问题”。非遗专题也可以按材料、工序、地区和来源来整理。','Try three lines: what it says, what evidence or example supports it, and what question remains. For a heritage entry, add material, process, region and source.'),
 faq('revision','怎么复习|记不住|复习方法|how to revise|remember what i learn','读完后先合上资料，用自己的话说出要点，再回去核对漏掉的地方。过一段时间换一个例子再解释一次。本站小测可以检查基础理解，但不必把分数当成全部收获。','Close the material and explain the key points in your own words, then check omissions. Later, explain again with another example. The site quiz checks basics; a score is not the whole learning outcome.'),
 faq('presentation','怎么做汇报|演讲紧张|项目怎么介绍|面试介绍|present a project|give a presentation','围绕一个真实问题讲：原来有什么不方便，你用了什么办法，具体做了什么，结果如何验证。演示时挑两三条完整操作；不熟悉的部分先查清，不用靠堆技术名词撑内容。','Explain one real problem: what was difficult, your approach, what you changed and how you checked it. Demonstrate two or three complete flows. Verify unfamiliar details rather than filling space with terminology.'),
 faq('reading-habit','读不下去|怎么开始阅读|阅读习惯|start reading|reading habit','先选一篇短而感兴趣的内容，带着一个问题读，读完只记一条收获。今天可以从一张非遗图片出发，再读它对应的专题，而不用一下浏览全部资料。','Choose a short topic you like, read with one question and record one takeaway. A photo and its related entry can be a manageable starting point instead of reading the whole collection.'),
 faq('language-study','英语怎么学|学英语|英文看不懂|learn english|study english','可以用本站双语资料做小练习：先读中文确定意思，再读英文找名称、材料和动作词；最后用两三句自己的话解释。遇到不熟悉的词放回原句理解，不必一次记住所有词。','Use a bilingual entry: understand the Chinese meaning, then locate names, materials and action words in English. Explain it in two or three sentences. Learn unfamiliar words in their sentences rather than all at once.'),
 faq('weekend','周末怎么安排|周末干什么|周末去哪|weekend plan|what to do this weekend','可以给周末留“一个出门点、一个整理任务、一段空白”。出门点不必很多，选一个博物馆或文化场所慢慢看；开放和预约先查官方信息，再安排交通。','Try one outing, one small organising task and some unplanned time. One museum or cultural venue can be enough. Check official opening and booking details before arranging transport.'),
 faq('packing','出门带什么|出行清单|旅行带什么|参观带什么|packing list|what to bring|what should i bring','参观前可以检查：预约或证件、手机电量、路线、适合天气的衣物，以及你日常需要的物品。轻装一些，场馆对包、饮食和摄影的要求以其公告为准。','Before a visit, check booking or ID, phone charge, route, weather-appropriate clothing and your usual essentials. Pack lightly and follow venue rules for bags, food and photography.'),
 faq('rain','下雨怎么玩|雨天安排|雨天出行|rainy day plan','雨天可以优先考虑室内场馆，减少跨城和露天转场；先确认交通与场馆公告。若不想出门，也可以选一个专题，把图片、导读与三维分开慢慢看。','Consider an indoor venue and fewer exposed or intercity transfers, checking transport and venue notices. Staying in with an entry’s photographs, guide and optional 3D view is another choice.'),
 faq('museum-etiquette','博物馆礼仪|参观注意|看展注意|museum etiquette|gallery etiquette','先看场馆提示，是否可拍摄、是否允许闪光灯、能否触摸都按现场规则。为别人留出观看距离，听讲解时控制音量；不确定时问工作人员。','Follow venue signs on photography, flash and touching. Leave viewing space, keep sound considerate and ask staff when unsure.'),
 faq('photo-notes','怎么拍展品|拍照技巧|拍非遗|photograph an exhibit','先确认允许拍摄，再观察光线、轮廓和背景；可以分别记录整体、局部和说明牌。别为了构图越过隔离线，发布时写清项目与地区，并遵守场馆及作品授权要求。','Confirm photography is allowed, then observe light, shape and background. Record an overall view, a detail and the label without crossing barriers. When sharing, name the project and region and follow relevant permissions.'),
 faq('travel-budget','旅行怎么做预算|出行预算|参观预算|travel budget','先列交通、门票或预约、餐食和备用四类，只填你已经核对的价格。把“必须支出”和“可选体验”分开，留一点弹性；我没有实时票价，金额要去官方渠道确认。','List transport, admission or bookings, meals and contingency using checked prices. Separate essentials from optional experiences and allow some flexibility. I do not have live ticket prices.'),
 faq('solo-visit','一个人去看展|独自旅行|独自参观|solo museum visit','一个人看展可以按自己的节奏来。提前确认路线和返程方式，选少量感兴趣的展项，适时休息；需要时把行程告诉信任的人，不必把每个展柜都看完。','A solo visit lets you set your pace. Check travel and return arrangements, choose a few exhibits and take breaks. Share plans with someone trusted when useful; you need not see every case.'),
 faq('family-visit','带孩子看展|亲子参观|带父母参观|family museum visit','把目标缩小为几个适合同行者的展项，提前看无障碍、休息和服务信息。可以让大家各选一个喜欢的细节再分享，而不是一路讲完所有知识。','Choose a few exhibits suited to your companions and check access, seating and services. Let each person share one favourite detail instead of trying to explain everything.'),
 faq('eat','今天吃什么|午饭吃什么|晚饭吃什么|不知道吃什么|what should i eat|lunch idea|dinner idea','可以先在自己方便、吃得惯的选择里挑：家常面饭、简单自做的一餐，或平时熟悉的店。结合口味、过敏和个人饮食要求决定；我不能查询附近店铺或替代专业饮食建议。','Choose something convenient and familiar, such as a simple home meal or a usual place. Consider your preferences, allergies and dietary requirements. I cannot find nearby restaurants or provide personalised nutrition advice.'),
 faq('cook','做饭没思路|懒得做饭|做饭安排|meal planning|plan meals','先看看已有食材和可用时间，再决定做一餐还是留一点给下一餐。把清单写得短一些，少买这次用不上的东西；具体烹饪与保存要求按可靠食谱和食品说明操作。','Check ingredients and available time, then plan one meal or a useful extra portion. Keep the shopping list short. Follow reliable recipes and food instructions for cooking and storage.'),
 faq('tidy','房间好乱|怎么收拾|整理桌面|收纳|tidy my room|organise my desk','先只清一块能看见的区域，比如桌面的一角。把东西分成“马上要用、归位、暂不处理”，不要一开始就把整个房间翻出来。完成一小块后再决定是否继续。','Start with one visible area, such as a desk corner. Sort into needed now, put away, and decide later. Avoid emptying the whole room at once; finish one area before continuing.'),
 faq('shopping','买东西纠结|购物纠结|总想买东西|shopping decision','可以先问：现在解决什么需要，手头有没有替代品，之后是否仍想要？把非急需的东西先记下来，过一段时间再看，比在疲惫时立即决定更容易想清楚。','Ask what need it serves, whether you already have an alternative, and whether you will still want it later. Note non-urgent items and revisit them rather than deciding immediately when tired.'),
 faq('communication','怎么开口|沟通不顺|和朋友沟通|communication advice','试着描述具体事情和自己的感受，再提出一个明确请求，例如“这次我没听清，能再解释一下吗？”。也留时间听对方怎么理解；一条消息不必解决整段关系。','Describe a specific event and your feeling, then make a clear request, such as asking for another explanation. Leave room for the other person’s view; one message need not solve an entire relationship.'),
 faq('thanks-message','感谢的话怎么写|怎么表达感谢|写感谢|write a thank you','可以用“具体帮助＋产生的作用＋一句感谢”：例如“谢谢你帮我核对资料，让我少走了不少弯路。这次真的很受用。”按真实情况改，比套很大的形容词更自然。','Use specific help, its effect and a thank-you: “Thank you for checking the material; it helped me avoid confusion.” Adapt it truthfully rather than relying on grand phrases.'),
 faq('rest','怎么放松|休息一下|休息方法|relax a little|take a break','可以暂时离开当前任务，看看远处、听一段喜欢的声音，或做一件不用交成果的小事。选让你舒服的方式就好，休息本身不需要再变成一项考核。','Step away from the task, look outside, listen to something you enjoy or do a small activity with no output required. Choose what feels comfortable; rest need not become another performance task.'),
 faq('sleep','睡不着|睡眠不好|晚睡|睡眠习惯|cannot sleep|sleep routine|trouble sleeping','可以先尝试稳定起床和睡觉的时间，睡前留一点放松时间，并减少临睡前刷屏。若睡眠问题反复发生、影响日常生活，建议咨询合适的医疗专业人员；我不能诊断或推荐药物。','Try a regular sleep and wake routine, some wind-down time and less screen use near bedtime. If problems recur and affect daily life, consult an appropriate healthcare professional. I cannot diagnose or recommend medication.','life',[sleepSource]),
 faq('habit','坚持不了|养成习惯|习惯怎么养成|build a habit|stick to a habit','把新习惯接在已有动作后面，例如“晚饭后读一小段资料”。先让动作小到容易完成，偶尔中断后从下一次继续，不必把一次漏做看成全部失败。','Attach a small action to an existing routine, such as a short reading after dinner. Keep it manageable and resume after a missed session; one gap does not erase all progress.'),
 faq('creativity','没灵感|创作灵感|设计没思路|creative block|no inspiration','先收集少量具体线索：一张纹样、一种材料、一段故事。写清自己喜欢的是形状、节奏还是含义，再做两个小草稿。借鉴时保留来源，别把别人的作品直接当自己的成果。','Collect a few concrete clues: a pattern, material or story. Identify whether form, rhythm or meaning interests you, then make two small sketches. Keep sources and do not present another person’s work as your own.'),
 faq('journaling','今天不知道写什么|日记怎么写|记录一天|journal prompt','可以写三句：今天看到了什么、哪件事让我有感受、明天想给自己留什么。参观日记还可以加一张图和它的来源，不必追求每次都写得很长。','Write three sentences: what you noticed, what affected you, and what you want to leave for tomorrow. A visit journal can add one image with its source; it need not be long.'),
 faq('digital-break','屏幕看累|总看手机|数字休息|screen break|phone break','先把下一次看手机的目的说清楚，把无关提醒暂时收起，留一段不需要屏幕的活动。若只是想放松，可以选择短暂离屏，而不是从一个应用换到另一个应用。','Name the purpose of your next phone check, put unrelated notifications aside and leave room for a screen-free activity. A break can mean stepping away rather than switching apps.'),
 faq('lost-item','东西找不到|忘带东西|找不到钥匙|lost my keys|misplaced something','先暂停翻找，回想最后一次使用的位置，再按“人刚经过的路线”检查固定几处。找到后可以选一个固定归位点；出门前只检查最关键的几件东西。','Pause and recall where you last used it, then check a few places along your recent path. Once found, choose a regular home for it and a short essentials check before leaving.'),
 faq('rain-check','要不要带伞|穿什么出门|出门穿什么|bring an umbrella|what to wear','我没有实时天气。先查看当地气象信息，再按温度、降雨与行程选择衣物；去室内场馆也可以留意空调和步行距离。','I do not have live weather. Check a local forecast before choosing clothing for temperature, rain and your plans, including indoor conditions and walking distance.'),
 faq('encourage','鼓励我|给我加油|我能做到吗|encourage me|cheer me up','可以先把今天的目标缩小到一个能完成的动作。你不需要同时证明所有能力；把这一步做完，再回看哪里比刚才清楚了一点。','Choose one manageable action today. You do not need to prove every ability at once; finish this step and notice what is a little clearer than before.'),
 faq('joke','讲个笑话|来个笑话|tell a joke','展馆里的陶罐说：“别看我不说话，我肚子里的故事可不少。”——这是小楚编的一句轻松话，不是非遗史料。','A pottery jar says, “I may be quiet, but I have a belly full of stories.” Just a playful line from Xiaochu, not a historical claim.'),
 faq('poem','写一句祝福|送我一句话|一句祝福|a kind wish|give me a wish','愿你今天有一件小事顺心，也给自己留一点慢慢来的余地。','May one small thing go well for you today, with a little room to take your time.'),
 faq('capability-limit','能联网吗|能查实时吗|能搜全网吗|browse the internet|can you search the web','我不会联网搜索或自由生成答案，而是查本站内容和整理好的问答。你可以点击回答附带的来源继续核对；实时天气、票价和开放安排要去相应官方渠道查看。','I do not browse the web or freely generate answers. I use this collection and curated cards. Follow source links to verify details; check official services for live weather, prices and opening arrangements.','site'),
];

const categoryGuides=[
 ['民间文学','folk literature','以讲述、传说等口头表达为观察入口，注意不同地区和讲述版本。','Explore oral expression such as stories and legends, paying attention to regional and narrative versions.'],
 ['传统音乐','traditional music','从旋律、节奏、声部与演奏场景理解音乐，资料与录音的来源要分开核对。','Consider melody, rhythm, parts and performance contexts; check the sources of texts and recordings separately.'],
 ['传统舞蹈','traditional dance','观察动作、步伐、队形与节庆或社区生活的关系。','Observe movement, steps and formations in relation to festivals or community life.'],
 ['传统戏剧','traditional theatre','可以从唱腔、角色、语言、舞台动作和故事理解地方剧种。','Explore a theatre tradition through voices, roles, language, action and stories.'],
 ['曲艺','narrative arts','留意说、唱、伴奏和叙事如何配合，并核对具体曲种。','Notice the relation between speech, singing, accompaniment and storytelling in a specific form.'],
 ['传统体育、游艺与杂技','traditional sports','阅读动作、器具和传习背景；高难或危险动作不适合自行模仿。','Learn about movement, equipment and transmission; difficult or dangerous acts are not activities to imitate unsupervised.'],
 ['传统美术','traditional fine arts','从材料、造型、色彩、纹样和构图观察作品，也关心制作的人与场景。','Look at material, form, colour, pattern and composition, alongside makers and contexts.'],
 ['传统技艺','traditional craftsmanship','可以按原料、成型、加工、装饰和使用来提问，具体步骤以项目资料为准。','Ask about material, shaping, processing, decoration and use; rely on the specific entry for actual steps.'],
 ['传统医药','traditional medicine','本站从文化历史与传承角度介绍相关项目，不提供诊断、用药或自行治疗操作。','The gallery discusses cultural history and transmission, not diagnosis, medication or self-treatment instructions.'],
 ['民俗','folk customs','关注节庆、礼俗与共同生活的场景；到访或记录时尊重当地规则和意愿。','Consider festivals, customs and shared life, respecting local rules and wishes when visiting or documenting.'],
];
for(const [name,en,zh,english] of categoryGuides)KNOWLEDGE_CARDS.push(faq('category-'+name,`什么是${name}|${name}是什么|${name}怎么看|what is ${en}`,zh,english,'culture',[heritageSource]));

export const normalise=value=>String(value??'').normalize('NFKC').toLowerCase().replace(/[鐘遺藝戲傳統學習圖館]/g,c=>({'鐘':'钟','遺':'遗','藝':'艺','戲':'戏','傳':'传','統':'统','學':'学','習':'习','圖':'图','館':'馆'}[c])).replace(/[\s\p{P}\p{S}]+/gu,' ').trim();
const compact=s=>normalise(s).replaceAll(' ','');
const escapeRegex=s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
function has(text,term){const t=normalise(term);return /[\u3400-\u9fff]/.test(t)?compact(text).includes(compact(t)):new RegExp(`(^|[^a-z0-9])${escapeRegex(t)}([^a-z0-9]|$)`,'i').test(normalise(text));}
const manualAliases={pottery:['毛家窑','毛家窑陶器','竹溪陶器','maojiayao','maojia kiln','pottery'],wood:['通山木雕','tongshan wood carving','tongshan woodcarving'],chime:['编钟','曾都编钟','青铜编钟制作技艺','chime bells','zengdu bells'],opera:['荆州花鼓戏','jingzhou flower drum opera'],lacquer:['楚式漆器','楚式漆器髹饰技艺','chu lacquerware'],music:['宜昌丝竹','细乐','yichang sizhu']};
const craftTerms=['木雕','编钟','汉绣','刺绣','剪纸','皮影','楚剧','黄梅戏','花鼓戏','糖塑','糖画','漆器','陶器','龙舞','狮舞','民歌','渔鼓','竹编','土家族'];
const named=exhibits.map(item=>({item,names:[item.title,item.english?.title,...(manualAliases[item.id]||[]),...(item.title.match(/[（(]([^）)]+)[）)]/)?.slice(1)||[])].filter(Boolean)}));
const byId=new Map(exhibits.map(e=>[e.id,e]));
const cityNames=[...new Set(exhibits.map(e=>e.city).filter(Boolean))];
const cityAlias=new Map(cityNames.map(city=>[city,[city,city.replace(/市$|土家族苗族自治州$|林区$/g,''),translateText(city,'en')]]));
cityAlias.get('恩施土家族苗族自治州')?.push('恩施','enshi');
const basicReply=(kind,title,paragraphs,more={})=>({kind,title,paragraphs:paragraphs.filter(Boolean),cards:[],actions:[],sources:[],suggestions:[],context:{},...more});
const textFor=(item,en)=>en?(item.english?.detail||'An English guide is not available for this entry.'):item.detail;
const titleFor=(item,en)=>en?(item.english?.title||item.title):item.title;
const sourceUnion=items=>[...new Map(items.flatMap(e=>e.sources||[]).map(s=>[s.url,s])).values()].slice(0,5);
const cardFor=(item,en)=>({type:'exhibit',id:item.id,title:titleFor(item,en),subtitle:en?translateText(item.region,'en')+' · '+translateText(item.category,'en'):item.region+' · '+item.category,excerpt:textFor(item,en).slice(0,160),image:item.image||'',scene:item.scene||null,hasPhoto:Boolean(item.photo)});
const sectionAction=section=>({type:'section',section});
const culturalSuggestions=(item,en)=>en?[`Where is ${titleFor(item,true)} from?`,`What should I observe in ${titleFor(item,true)}?`,...(item.scene?[`Show ${titleFor(item,true)} in 3D`]:[])]:[`${item.title}在哪里？`,`${item.title}有什么值得观察？`,...(item.scene?[`我想看${item.title}三维`]:[])];
function findCity(q){return [...cityAlias].find(([,aliases])=>aliases.some(a=>a&&has(q,a)))?.[0]||'';}
function findCategory(q){return categories.find(c=>has(q,c)||has(q,translateText(c,'en')))||'';}
function topicCandidates(q){
 return named.map(({item,names})=>{let score=0;for(const name of names){const n=compact(name);if(n.length<2)continue;if(compact(q)===n)score=Math.max(score,250+n.length);else if(has(q,name))score=Math.max(score,100+n.length);}
   for(const term of craftTerms)if(has(q,term)&&has(item.title,term))score=Math.max(score,40+term.length);
   if(score&&item.region&&has(q,item.region))score+=20;
   else if(score&&item.city&&[item.city,item.city.replace(/市$|土家族苗族自治州$|林区$/g,'')].some(c=>has(q,c)))score+=10;
   return {item,score};}).filter(e=>e.score>0).sort((a,b)=>b.score-a.score);
}
function matchFAQ(q){
 return KNOWLEDGE_CARDS.map(card=>{let score=0;for(const key of card.keys){if(['greeting','thanks','goodbye'].includes(card.id)){if(compact(q)===compact(key))score=Math.max(score,500+key.length);}else if(has(q,key))score=Math.max(score,(compact(q)===compact(key)?500:50)+key.length);}
   return {card,score};}).filter(x=>x.score).sort((a,b)=>b.score-a.score)[0]?.card;
}
function culturalAnswer(item,q,en){
 const title=titleFor(item,en),body=textFor(item,en),actions=[{type:'exhibit',id:item.id},{type:'map',id:item.id}];
 if(item.photo)actions.push({type:'photo',id:item.id});if(item.scene)actions.push({type:'scene',id:item.id,scene:item.scene});
 let paragraphs=[body],kind='entry';
 if(/起源|哪一年|哪个朝代|多少年历史|始于|创始人|传承人|何时|when did|which dynasty|what dynasty|origin date|when was|founder|inheritor|how old/i.test(q)){
   paragraphs=[en?'This entry does not provide enough verified detail to establish that exact date or person. Its recorded year is not automatically an origin date. Please check the linked sources.':'当前导读没有足够资料确定你问的准确年代或人物；名录里的记录年份也不能当成起源年份。可以继续查下方原始来源。',body];kind='limited';
 }else if(/材料|原料|什么做|made of|material/i.test(q)){
   const sentences=body.match(/[^。.!?]+[。.!?]?/g)||[];const hit=sentences.filter(s=>/材料|原料|木材|木胎|铜|锡|铅|糖料|麦芽糖|线材|布片|竹|mud|clay|wood|copper|tin|lead|sugar|material|thread|fabric/i.test(s));
   paragraphs=hit.length?hit.slice(0,2):[en?'This guide does not specify the exact material. Here is the available introduction; I will not infer a recipe from the name alone.':'当前资料未单独写明具体材料，下面是已收录介绍；我不会只凭名字补一份配方。',body];
 }else if(/工序|步骤|怎么做|如何制作|制作过程|process|how is it made|steps/i.test(q)){
   paragraphs=[body,en?'This is an introductory guide rather than a complete workshop procedure. The sources may have more detail.':'这是已有的工艺概述，不等于完整的操作教程；更详细的流程可继续查阅来源。'];
 }else if(/哪里|在哪|地区|where|region/i.test(q)){
   paragraphs=[en?`Recorded region: ${translateText(item.region,'en')}. This is a regional association, not an exact visiting entrance.`:`记录地区：${item.region}。这里说明项目所属地区，不代表可以直接到访的场馆入口。`];
 }else if(/观察|欣赏|特点|特色|observe|feature|special/i.test(q))paragraphs=[body,(en?item.english?.observations:item.observations)?.map((s,i)=>`${i+1}. ${s}`).join('\n')];
 if(/三维|模型|3d|model/i.test(q))paragraphs.push(item.scene?(en?'A retained 3D exhibit is available. Starting it is your choice and can download about 348 MiB of core resources.':'这个专题有保留的三维入口。请主动点击下方按钮；首次可能下载约348 MiB核心资源。'):(en?'This entry has no individual 3D model in the current gallery. You can still read the guide and see any linked photographs.':'这个专题当前没有独立三维模型，可以先看资料与已关联图片。'));
 if(/图片|照片|photo|image/i.test(q))paragraphs.push(item.photo?(en?`Linked image: ${item.photo.titleEn}. ${item.photo.scopeEn}.`:`关联图片：${item.photo.title}。${item.photo.scope}。`):(en?'No verified photo is linked to this entry yet.':'这条记录暂未关联经过核对的照片。'));
 return basicReply(kind,title,paragraphs,{cards:[cardFor(item,en)],actions,sources:sourceUnion([item]),suggestions:culturalSuggestions(item,en),context:{lastId:item.id}});
}

export function answerQuestion(input,{language='zh',context={},places=[],now=new Date()}={}){
 const en=language==='en',raw=String(input??'').trim().slice(0,500),q=normalise(raw);
 if(!q)return basicReply('empty',en?'What would you like to know?':'你想了解什么？',[en?'Enter a heritage name, a question about the gallery, or an everyday topic.':'可以输入非遗名称、展馆使用问题，或一个日常话题。']);
 // High-risk requests are not answered with a similar-looking cultural or lifestyle card.
 if(/自杀|自残|不想活|想死|结束生命|suicid|kill myself|hurt myself/i.test(raw))return basicReply('urgent',en?'Please get real-world support now':'请先联系现实中的支持',[en?'Your safety matters. If you might act on these thoughts or are in immediate danger, contact local emergency services or go to an emergency department. Reach someone you trust who can stay with you, and put distance between yourself and anything you might use to hurt yourself. This local guide cannot provide crisis care.':'你的安全很重要。如果你可能马上伤害自己，或正处在危险中，请联系当地紧急救助或前往急诊，并尽快联系能陪着你的信任的人。尽可能远离可能伤害自己的物品。本地知识助手不能提供危机干预。']);
 if(/药量|剂量|吃什么药|诊断|治疗方案|胸痛|呼吸困难|发烧|感冒|咳嗽|头痛|头疼|腹痛|胃疼|肚子疼|抑郁症|艾灸治|针灸治|能治好|用药|dosage|diagnos|what medicine|cure my|chest pain|cannot breathe/i.test(raw))return basicReply('health',en?'Health questions need appropriate help':'健康问题需要合适的帮助',[en?'I can discuss traditional medicine as cultural heritage, but cannot diagnose, prescribe or guide treatment. Please seek an appropriate healthcare professional; severe or urgent symptoms need local emergency care.':'我可以从文化与传承角度介绍传统医药，但不能诊断、开药或指导治疗。身体不适请向合适的医疗专业人员咨询；严重或紧急症状请及时寻求当地急救。']);
 if(/股票|炒股|投资建议|买哪只基金|法律诉讼|怎么打官司|stock pick|investment advice|legal advice/i.test(raw))return basicReply('professional',en?'Outside this guide’s scope':'这超出了小楚的资料范围',[en?'I do not provide personalised financial or legal advice. Please use appropriate qualified advice. I can help with heritage, gallery features or general everyday planning.':'我不提供个人投资或法律决策建议，相关事项请咨询合适的专业人员。非遗、展馆使用和一般日常安排，我可以继续帮你查。']);
 if(/天气|气温|实时路况|weather|temperature|live traffic/i.test(raw)&&!(/下雨怎么玩|雨天安排/.test(raw)))return basicReply('realtime',en?'Check a live service':'请查看实时信息',[en?'I cannot retrieve live weather or traffic. Check your local weather service or a navigation app before travelling. I can help you prepare a visit checklist.':'我没有实时天气或路况数据。出门前请查看当地气象信息或导航应用；如果需要，我可以帮你整理参观准备清单。'],{suggestions:en?['What should I bring?','Plan a rainy day']:['出门带什么？','雨天怎么安排？']});
 if(/今天几号|现在几点|星期几|what time|what date|day of the week/i.test(raw)){const date=new Date(now);return basicReply('clock',en?'Your device time':'按你的设备时间',[en?date.toLocaleString('en-GB',{dateStyle:'full',timeStyle:'short'}):date.toLocaleString('zh-CN',{dateStyle:'full',timeStyle:'short'})]);}
 if(context.selectedId&&byId.has(context.selectedId))return culturalAnswer(byId.get(context.selectedId),q,en);
 const faqHit=matchFAQ(q),matches=topicCandidates(q),city=findCity(q),category=findCategory(q);
 const explicit=matches.filter(m=>m.score>=100);
 if(faqHit&&(faqHit.group==='site'||!explicit.length)&&!(faqHit.id==='3d-help'&&explicit.length))return basicReply('faq',en?'Xiaochu’s guide':'小楚的回答',[en?faqHit.en:faqHit.zh],{sources:faqHit.sources,actions:faqHit.section?[sectionAction(faqHit.section)]:[],suggestions:faqHit.group==='life'?(en?['Recommend some heritage','Help me plan my day']:['今天推荐一个非遗','帮我安排一天']):(en?['What heritage is in Wuhan?','Which exhibits have 3D?']:['武汉有哪些非遗？','哪些展品能看三维？']),context:['greeting','thanks'].includes(faqHit.id)&&context.lastId?{lastId:context.lastId}:{}});
 if(/三维|3d|模型|model/i.test(q)&&!matches.length){const items=exhibits.filter(e=>e.scene);return basicReply('list',en?'Available 3D exhibits':'可以看三维的展品',[en?'These three entries link to retained 3D objects. The theatre is an additional scene in the 3D area. Chat does not download it automatically.':'这三条专题关联保留的三维器物；三维区另有戏台场景。聊天不会自动下载大资源。'],{cards:items.map(e=>cardFor(e,en)),actions:[sectionAction('experience')],sources:sourceUnion(items)});}
 if((/参观|场馆|博物馆|去哪看|哪里看|visit|museum|destination/i.test(q))&&!matches.length){const selected=places.filter(p=>!city||p.city===city);return basicReply('places',en?'Cultural visit destinations':'文化参观目的地',[selected.length?(en?'These are recorded destinations, not live opening or booking information. Confirm entrance and availability with the venue.':'以下是已收录目的地，开放、预约与入口仍以场馆官方信息为准。'):(en?'No matching destination is available in the loaded records. The map can still show regional heritage.':'当前已加载的目的地中没有匹配项，可以先在地图认识地区分布。')],{cards:selected.slice(0,8).map(p=>({type:'place',id:p.id,title:en?translateText(p.name,'en'):p.name,subtitle:en?translateText(p.city,'en'):p.city,excerpt:en?'Recorded public destination; see official sources for visiting details.':p.theme,address:p.address,sources:p.sources})),sources:sourceUnion(selected).slice(0,5),actions:[sectionAction('atlas')]});}
 if((city||category)&&(!explicit.length||/哪些|有哪些|推荐|列出|list|recommend|which/i.test(q))){const narrowed=new Set(matches.map(m=>m.item.id));const items=exhibits.filter(e=>(!city||e.city===city)&&(!category||e.category===category)&&(!matches.length||explicit.length||narrowed.has(e.id)));return basicReply('list',en?'Matching entries':'找到这些非遗记录',[en?`${items.length} matching regional entries and topics. Showing the first ${Math.min(items.length,8)}; use the collection for all results.`:`找到${items.length}条地区记录与专题，先展示${Math.min(items.length,8)}条；可到图鉴继续筛选。`],{cards:items.slice(0,8).map(e=>cardFor(e,en)),actions:[{type:'filter',city,category}],sources:sourceUnion(items.slice(0,3)),suggestions:en?['What are the ten categories?']:['非遗有哪些门类？']});}
 if(/推荐.*非遗|非遗.*推荐|随便.*非遗|recommend.*heritage|heritage.*recommend/i.test(q)){const ids=['wood','chime','lacquer'];return basicReply('list',en?'Three places to start':'从三个专题开始',[en?'Try one material and one observation question for each. These are editorial starting points, not a popularity ranking.':'可以从木纹、青铜与漆色分别入手，每篇带一个观察问题。这里只是入门推荐，不是热门排名。'],{cards:ids.map(id=>cardFor(byId.get(id),en)),sources:sourceUnion(ids.map(id=>byId.get(id)))});}
 if(matches.length){
   const strongest=matches[0].score,chosen=matches.filter(m=>m.score>=100||m.score===strongest),unique=[...new Map(chosen.map(m=>[m.item.id,m.item])).values()];
   const top=unique.filter(e=>chosen.find(m=>m.item.id===e.id).score===strongest);
   if(/区别|比较|有什么不同|difference|compare/i.test(q)&&unique.length===2)return basicReply('compare',en?'Compare the recorded descriptions':'对照已有资料看一看',unique.map(e=>`${titleFor(e,en)}：${textFor(e,en)}`),{cards:unique.map(e=>cardFor(e,en)),sources:sourceUnion(unique),suggestions:en?['What should I observe?']:['怎么观察一件作品？']});
   if(top.length===1&&strongest>=100)return culturalAnswer(top[0],q,en);
   if(unique.length===1)return culturalAnswer(unique[0],q,en);
   return basicReply('clarify',en?'Which regional entry do you mean?':'你想了解哪一个地区的项目？',[en?'Several entries match. Choose one so that details from different regions are not mixed.':'有多条相关记录，先选一条，避免把不同地区的介绍混在一起。'],{cards:unique.slice(0,8).map(e=>({...cardFor(e,en),type:'choice',question:titleFor(e,en)+' · '+(en?translateText(e.region,'en'):e.region)})),actions:[sectionAction('collection')]});
 }
 if(context.lastId&&byId.has(context.lastId)&&(/它|这个|刚才|材料呢|哪里呢|工序呢|图片呢|特点呢|^where is it|^what is it|^its |^what about|^show it|^and the /i.test(q)||/^(材料|地区|工序|特点|观察|图片|三维|material|region|process|features?)\s*[呢吗?？]*$/i.test(q)))return culturalAnswer(byId.get(context.lastId),q,en);
 // Conservative field retrieval: literal keywords offer candidates, never fabricated facts.
 const words=q.split(' ').filter(w=>w.length>=2&&!['what','which','about','please','tell','show','does','the','and','are','can','you'].includes(w));
 const candidates=words.length?exhibits.filter(e=>words.some(w=>has([e.title,e.region,e.category,e.detail,e.searchEnglish].join(' '),w))):[];
 if(candidates.length)return basicReply('related',en?'Related material, rather than a definite answer':'找到相关资料，暂不直接下结论',[en?'These records contain some of your words. Please choose an entry or make the question more specific.':'下面的记录包含相关关键词，暂时不足以直接回答你的问题。可以选择一条，或补充项目名称与想问的方面。'],{cards:candidates.slice(0,5).map(e=>({...cardFor(e,en),type:'choice',question:titleFor(e,en)}))});
 return basicReply('unknown',en?'That is not in my current knowledge':'这个问题暂时没有收录',[en?'I do not want to guess. Try a heritage name plus a question, such as “Tongshan wood carving materials”, or ask about study plans, museum visits or gallery help.':'我不想给你编一个看似完整的答案。可以试试“项目名称＋问题”，例如“通山木雕的材料”；也能问学习安排、参观准备或展馆使用。'],{suggestions:en?['What is intangible heritage?','What heritage is in Wuhan?','Help me plan my day']:['什么是非遗？','武汉有哪些非遗？','帮我安排一天']});
}

export const KNOWLEDGE_STATS=Object.freeze({entries:exhibits.length,categories:categories.length,cards:KNOWLEDGE_CARDS.length,lifeCards:KNOWLEDGE_CARDS.filter(c=>c.group==='life').length,siteCards:KNOWLEDGE_CARDS.filter(c=>c.group==='site').length,cultureCards:KNOWLEDGE_CARDS.filter(c=>c.group==='culture').length});
